package kr.or.arte.seal.statistics.application;import org.springframework.stereotype.Service;import java.time.*;import java.util.UUID;@Service public class StatisticsQueryService {private final StatisticsRepository repository;public StatisticsQueryService(StatisticsRepository r){repository=r;}public StatisticsSnapshot query(UUID actor,LocalDate from,LocalDate to){if(from==null||to==null||to.isBefore(from)||to.isAfter(from.plusYears(1)))throw new IllegalArgumentException("통계 기간은 순방향 최대 1년입니다.");return repository.query(actor,from,to);}}
